import {moveBlock,moveConflicts,readMoves,resetMovedBlock,saveMoves,resolveMoveSource} from '../core/moves.js';
import {blocksFor} from '../core/sessions.js';
import {addDays,dateKey} from '../core/model.js';
import {courseFingerprint} from '../core/overrides.js';
const weekdays=['周一','周二','周三','周四','周五','周六','周日'];
export function mountMoveDialog(){
 if(document.getElementById('move-sheet'))return;
 const dialog=document.createElement('dialog');dialog.id='move-sheet';dialog.className='sheet';
 dialog.innerHTML='<div class="sheet-handle"></div><div class="sheet-title"><h2>调整上课时间</h2><button class="plain-icon" data-close="move-sheet" aria-label="关闭调课">✕</button></div><p id="move-source" class="sheet-tip"></p><form id="move-form"><div class="move-target-fields"><label>调到哪天<select id="move-day"></select></label><label>从第几节开始<select id="move-period"></select></label></div><label class="move-scope-label">修改范围<select id="move-scope"><option value="once">只改这一次</option><option value="following">从本周起，后续已排课的周都改</option></select></label><p id="move-preview" class="move-preview"></p><p id="move-conflicts" class="move-warning" role="status"></p><label id="move-confirm-label" class="move-confirm" hidden><input id="move-allow-conflict" type="checkbox">我已核对重叠课程，仍按此时间调课</label><p id="move-error" class="move-error" role="status"></p><div class="move-actions"><button type="submit" class="primary-button" id="move-save">确认调课</button><button type="button" id="move-reset" class="secondary-button">恢复原上课时间</button></div></form><p class="sheet-tip">只保存在本机，学校原始课表和左侧作息不改。刷新教务后保留；恢复时采用最新教务安排。</p>';
 document.body.append(dialog);
}
export function setupMoves({getContext,notify,openSheet,onChange,storage=globalThis.localStorage}){
 mountMoveDialog();const $=selector=>document.querySelector(selector),grid=$('#timetable');let selection=null,pointer=null,hold=0,ghost=null,target=null;
 function contextFor(block,week){const context=getContext(),original=context.rawCourses.find(c=>c.id===(block.originalId||block.id));if(!original)throw Error('原课程不存在，请重新同步或从课表打开');const delta=block.move?.delta||0;return {...context,original,block,week,sourceStart:block.start-delta,sourceEnd:block.end-delta};}
 function options(){if(!selection)return null;const {schoolId,week,sourceStart,sourceEnd,rawCourses}=selection;return {schoolId,week,sourceStart,sourceEnd,sourceCourses:rawCourses,targetDay:Number($('#move-day').value),targetStart:Number($('#move-period').value),scope:$('#move-scope').value};}
 function preview(){if(!selection)return;const o=options(),{settings,original}=selection,count=o.sourceEnd-o.sourceStart+1,targetEnd=o.targetStart+count-1;$('#move-error').textContent='';$('#move-allow-conflict').checked=false;
  $('#move-reset').hidden=!readMoves(storage).entries.some(e=>e.schoolId===selection.schoolId&&e.startDate===settings.startDate&&resolveMoveSource(e,selection.rawCourses)===original.id&&(o.scope==='following'?e.week>=selection.week:e.week===selection.week)&&e.period>=o.sourceStart&&e.period<=o.sourceEnd);
  if(targetEnd>12){$('#move-preview').textContent='这个课块有 '+count+' 个小节，目标位置放不下。';$('#move-conflicts').textContent='';$('#move-confirm-label').hidden=true;$('#move-save').disabled=true;return;}
  $('#move-save').disabled=false;const date=dateKey(addDays(settings.startDate,(o.week-1)*7+o.targetDay-1));$('#move-preview').textContent=`调课后：${date} ${weekdays[o.targetDay-1]} · 第 ${o.targetStart===targetEnd?o.targetStart:o.targetStart+'–'+targetEnd} 节 · ${settings.times[o.targetStart-1].split('-')[0]}–${settings.times[targetEnd-1].split('-')[1]}。`+(o.scope==='following'?'同时应用于后续仍排有该课的周。':'只改变这一次。');
  const weeks=o.scope==='following'?original.weeks.filter(w=>w>=o.week&&w<=settings.totalWeeks):[o.week],clashes=[];for(const w of weeks)for(const c of moveConflicts(selection.courses,settings,original,{...o,week:w}))clashes.push({week:w,course:c});selection.conflicts=clashes;
  $('#move-conflicts').textContent=clashes.length?'与以下安排重叠：'+[...new Set(clashes.map(x=>'第'+x.week+'周 '+x.course.name))].slice(0,6).join('、')+(clashes.length>6?' 等':'')+'。请先核对。':'';$('#move-confirm-label').hidden=!clashes.length;
 }
 function open(block,week,destination){try{selection=contextFor(block,week);const {original,settings,sourceStart,sourceEnd}=selection;$('#move-source').textContent=`${original.name} · 原${weekdays[original.day-1]}第 ${sourceStart===sourceEnd?sourceStart:sourceStart+'–'+sourceEnd} 节 · 本次移动 ${sourceEnd-sourceStart+1} 个小节`;
   $('#move-day').innerHTML=weekdays.map((name,i)=>`<option value="${i+1}">${name}</option>`).join('');$('#move-period').innerHTML=settings.times.map((time,i)=>`<option value="${i+1}">第 ${i+1} 节 · ${time}</option>`).join('');$('#move-day').value=destination?.day||block.day;$('#move-period').value=destination?.period||block.start;$('#move-scope').value='once';preview();openSheet('#move-sheet');
  }catch(error){notify(error.message);}}
 for(const id of ['move-day','move-period','move-scope'])$('#'+id).addEventListener('change',preview);
 $('#move-form').onsubmit=e=>{e.preventDefault();if(!selection)return;try{previewIfStale();if(selection.conflicts?.length&&!$('#move-allow-conflict').checked)throw Error('请先核对并确认重叠课程');const {original,settings}=selection,next=moveBlock(readMoves(storage),original,settings,options());saveMoves(next,storage);$('#move-sheet').close();onChange();notify('已保存调课，学校原始安排保持不变');}catch(error){$('#move-error').textContent=error.message;}};
 function previewIfStale(){const latest=getContext();selection.courses=latest.courses;const o=options(),weeks=o.scope==='following'?selection.original.weeks.filter(w=>w>=o.week&&w<=selection.settings.totalWeeks):[o.week];selection.conflicts=weeks.flatMap(w=>moveConflicts(latest.courses,selection.settings,selection.original,{...o,week:w}));}
 $('#move-reset').onclick=()=>{if(!selection)return;try{const next=resetMovedBlock(readMoves(storage),selection.original,selection.settings,options());saveMoves(next,storage);$('#move-sheet').close();onChange();notify('已恢复原上课时间');}catch(error){$('#move-error').textContent=error.message;}};
 function blockAt(card){const context=getContext();return blocksFor(context.courses,context.week,null,context.settings.times).find(c=>c.id===card.dataset.course&&c.day===Number(card.dataset.day)&&c.start===Number(card.dataset.period));}
 function destination(x,y){const rect=grid.getBoundingClientRect(),days=[...document.querySelectorAll('.date-day')];if(y<rect.top||y>rect.bottom)return null;const column=days.findIndex(el=>{const r=el.getBoundingClientRect();return x>=r.left-3&&x<=r.right+3;});if(column<0)return null;return {day:column+1,period:Math.min(12,Math.max(1,Math.floor((y-rect.top)/(rect.height/12))+1))};}
 function drawTarget(next){for(const node of grid.querySelectorAll('.move-drop-target'))node.classList.remove('move-drop-target');target=next;if(!next||!pointer)return;const count=pointer.block.end-pointer.block.start+1;for(const node of grid.querySelectorAll('.grid-guide'))if(Number(node.dataset.clockDay)===next.day&&Number(node.dataset.clockPeriod)>=next.period&&Number(node.dataset.clockPeriod)<next.period+count)node.classList.add('move-drop-target');if(ghost)ghost.querySelector('small').textContent=weekdays[next.day-1]+' · 第'+next.period+'节起';}
 function activate(){if(!pointer||pointer.active)return;pointer.active=true;window.__courseMoveDrag=true;grid.classList.add('is-moving');pointer.card.classList.add('is-drag-source');try{pointer.card.setPointerCapture(pointer.id);}catch{}ghost=document.createElement('div');ghost.className='course-move-ghost';const name=document.createElement('strong');name.textContent=pointer.block.name;ghost.append(name,document.createElement('small'));document.body.append(ghost);position(pointer.x,pointer.y);notify('拖到目标日期和节次，松手后核对');}
 function position(x,y){if(!ghost)return;ghost.style.left=x+'px';ghost.style.top=y+'px';drawTarget(destination(x,y));const canvas=grid.closest('.app-canvas');if(canvas){const r=canvas.getBoundingClientRect();if(y>r.bottom-55)canvas.scrollTop+=18;else if(y<r.top+55)canvas.scrollTop-=18;}}
 function clear(){clearTimeout(hold);if(pointer?.card)pointer.card.classList.remove('is-drag-source');pointer=null;ghost?.remove();ghost=null;drawTarget(null);grid.classList.remove('is-moving');window.__courseMoveDrag=false;}
 grid.addEventListener('pointerdown',e=>{const card=e.target.closest('.course-card');if(!card||e.button!==0||document.querySelector('dialog[open]'))return;const block=blockAt(card);if(!block)return;clear();pointer={id:e.pointerId,x:e.clientX,y:e.clientY,card,block,active:false,type:e.pointerType};if(e.pointerType!=='mouse')hold=setTimeout(activate,420);});
 grid.addEventListener('pointermove',e=>{if(!pointer||pointer.id!==e.pointerId)return;const distance=Math.hypot(e.clientX-pointer.x,e.clientY-pointer.y);if(!pointer.active){if(pointer.type==='mouse'&&distance>6)activate();else if(pointer.type!=='mouse'&&distance>12){clear();return;}}if(pointer?.active){e.preventDefault();position(e.clientX,e.clientY);}});
 function finish(e){if(!pointer)return;const active=pointer.active,block=pointer.block,week=getContext().week,next=target;if(active){window.__courseMoveConsumedUntil=Date.now()+700;e.preventDefault();}clear();if(active&&next)open(block,week,next);else if(active)notify('没有放到课表内，本次没有修改');}
 grid.addEventListener('pointerup',e=>{if(pointer?.id===e.pointerId)finish(e);});grid.addEventListener('pointercancel',()=>{if(pointer?.active&&pointer.type==='touch')return;clear();});
 grid.addEventListener('click',e=>{if(Date.now()<(window.__courseMoveConsumedUntil||0)){e.preventDefault();e.stopImmediatePropagation();}},true);
 grid.addEventListener('contextmenu',e=>{if(pointer)e.preventDefault();});document.addEventListener('touchmove',e=>{if(pointer?.active){e.preventDefault();const touch=e.touches[0];if(touch)position(touch.clientX,touch.clientY);}},{passive:false});document.addEventListener('touchend',e=>{if(pointer?.active&&pointer.type==='touch')finish(e);},{passive:false});document.addEventListener('touchcancel',clear);
 return {open,detail({block,week}){const host=$('#detail-content');if(!block||!host)return;const button=document.createElement('button');button.type='button';button.className='move-detail-button';button.textContent='调整这块课的上课时间';button.onclick=()=>open(block,week);host.append(button);}};
}
